<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f16;
      --bg-elevated: #111827;
      --bg-soft: #161f2f;
      --border: rgba(255, 255, 255, 0.1);
      --border-strong: rgba(255, 255, 255, 0.18);
      --text: #e5eefb;
      --muted: #9fb0c8;
      --accent: #8ab4ff;
      --danger: #ff6b6b;
      --danger-strong: #ff8585;
      --shadow: 0 32px 80px rgba(0, 0, 0, 0.45);
      --radius-lg: 24px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --focus: #c7dcff;
    }

    * {
      box-sizing: border-box;
    }

    html {
      color-scheme: dark;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(138, 180, 255, 0.15), transparent 30%),
        linear-gradient(180deg, #111827 0%, #0b0f16 100%);
      color: var(--text);
      line-height: 1.5;
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: #ffffff;
      color: #0b0f16;
      transform: translateY(-200%);
      transition: transform 0.2s ease;
      z-index: 20;
      text-decoration: none;
      font-weight: 600;
    }

    .skip-link:focus-visible {
      transform: translateY(0);
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4rem 1.25rem;
    }

    .preview-shell {
      width: min(100%, 920px);
      padding: clamp(1.25rem, 2vw, 1.75rem);
      border: 1px solid var(--border);
      border-radius: calc(var(--radius-lg) + 8px);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.015));
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .preview-header {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1.25rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 3vw, 2.6rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lede {
      margin: 0.4rem 0 0;
      color: var(--muted);
      max-width: 56ch;
    }

    .status {
      min-height: 1.5em;
      color: var(--accent);
      font-weight: 600;
      text-align: right;
    }

    .card {
      overflow: hidden;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      background: rgba(7, 11, 18, 0.7);
    }

    figure {
      margin: 0;
    }

    .image-frame {
      aspect-ratio: 16 / 10;
      overflow: hidden;
      background: linear-gradient(180deg, #172136 0%, #0e1420 100%);
      border-bottom: 1px solid var(--border);
    }

    .image-frame img {
      width: 100%;
      height: 100%;
      display: block;
      object-fit: cover;
    }

    figcaption {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
    }

    .caption-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .meta {
      margin: 0;
      color: var(--muted);
    }

    .trigger,
    .secondary-button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
    }

    .trigger {
      background: linear-gradient(180deg, rgba(255, 111, 111, 0.95), rgba(198, 52, 52, 0.95));
      color: #fff;
      box-shadow: 0 12px 26px rgba(255, 95, 95, 0.22);
    }

    .trigger:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 30px rgba(255, 95, 95, 0.26);
    }

    .secondary-button {
      background: rgba(255, 255, 255, 0.04);
      color: var(--text);
      border-color: var(--border-strong);
    }

    .secondary-button:hover {
      background: rgba(255, 255, 255, 0.07);
    }

    .trigger:focus-visible,
    .secondary-button:focus-visible,
    .dialog-button:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    dialog {
      width: min(92vw, 30rem);
      border: 1px solid var(--border-strong);
      border-radius: 24px;
      padding: 0;
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(11, 15, 22, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(4, 8, 15, 0.72);
      backdrop-filter: blur(10px);
    }

    .dialog-card {
      padding: 1.4rem;
      display: grid;
      gap: 1rem;
    }

    .dialog-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      width: fit-content;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: rgba(255, 107, 107, 0.12);
      color: var(--danger-strong);
      border: 1px solid rgba(255, 107, 107, 0.2);
      font-size: 0.875rem;
      font-weight: 700;
    }

    .dialog-card h2 {
      margin: 0;
      font-size: 1.35rem;
      line-height: 1.2;
      letter-spacing: -0.02em;
    }

    .dialog-card p {
      margin: 0;
      color: var(--muted);
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .dialog-button {
      min-width: 7rem;
      padding: 0.85rem 1.1rem;
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      border: 1px solid transparent;
      transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease;
    }

    .dialog-button:hover {
      transform: translateY(-1px);
    }

    .dialog-button.cancel {
      background: rgba(255, 255, 255, 0.05);
      color: var(--text);
      border-color: var(--border-strong);
    }

    .dialog-button.delete {
      background: linear-gradient(180deg, rgba(255, 107, 107, 1), rgba(214, 68, 68, 1));
      color: #fff;
      box-shadow: 0 12px 26px rgba(255, 95, 95, 0.18);
    }

    .dialog-button.delete:hover {
      box-shadow: 0 16px 30px rgba(255, 95, 95, 0.24);
    }

    .empty-state {
      padding: 3rem 1.25rem;
      text-align: center;
      color: var(--muted);
    }

    .empty-state strong {
      display: block;
      margin-bottom: 0.4rem;
      color: var(--text);
      font-size: 1.1rem;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 640px) {
      main {
        padding: 3.5rem 0.75rem;
      }

      .preview-header,
      .caption-row {
        align-items: start;
        flex-direction: column;
      }

      .status {
        text-align: left;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-button,
      .trigger,
      .secondary-button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#content">Skip to content</a>

  <main id="content">
    <section class="preview-shell" aria-labelledby="page-title">
      <div class="preview-header">
        <div>
          <h1 id="page-title">Image preview</h1>
          <p class="lede">Review the photo before removing it from your library.</p>
        </div>
        <p class="status" id="status" aria-live="polite"></p>
      </div>

      <article class="card" aria-labelledby="photo-title">
        <figure>
          <div class="image-frame">
