              src="data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%27http%3A//www.w3.org/2000/svg%27%20viewBox%3D%270%200%201600%201000%27%20role%3D%27img%27%20aria-labelledby%3D%27title%20desc%27%3E%3Ctitle%3EMountain%20lake%20at%20dusk%3C/title%3E%3Cdesc%3EA%20calm%20mountain%20lake%20with%20soft%20sunset%20light%2C%20distant%20trees%2C%20and%20reflections%20on%20the%20water.%3C/desc%3E%3Cdefs%3E%3ClinearGradient%20id%3D%27sky%27%20x1%3D%270%27%20y1%3D%270%27%20x2%3D%270%27%20y2%3D%271%27%3E%3Cstop%20offset%3D%270%25%27%20stop-color%3D%27%23233657%27/%3E%3Cstop%20offset%3D%2770%25%27%20stop-color%3D%27%236a4d82%27/%3E%3Cstop%20offset%3D%27100%25%27%20stop-color%3D%27%230c1321%27/%3E%3C/linearGradient%3E%3ClinearGradient%20id%3D%27water%27%20x1%3D%270%27%20y1%3D%270%27%20x2%3D%270%27%20y2%3D%271%27%3E%3Cstop%20offset%3D%270%25%27%20stop-color%3D%27%2317263c%27/%3E%3Cstop%20offset%3D%27100%25%27%20stop-color%3D%27%2307121f%27/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect%20width%3D%271600%27%20height%3D%271000%27%20fill%3D%27url(%23sky)%27/%3E%3Ccircle%20cx%3D%271220%27%20cy%3D%27200%27%20r%3D%2780%27%20fill%3D%27%23ffd59a%27%20opacity%3D%27.9%27/%3E%3Cpath%20d%3D%27M0%20630%20L240%20520%20L420%20595%20L620%20470%20L820%20520%20L1080%20430%20L1260%20500%20L1600%20410%20V1000%20H0Z%27%20fill%3D%27%23111b2e%27/%3E%3Cpath%20d%3D%27M0%20695%20L210%20610%20L420%20682%20L650%20578%20L830%20620%20L1040%20545%20L1240%20608%20L1600%20530%20V1000%20H0Z%27%20fill%3D%27%231b2942%27/%3E%3Cpath%20d%3D%27M0%20555%20L1600%20555%20V1000%20H0Z%27%20fill%3D%27url(%23water)%27/%3E%3Cg%20opacity%3D%27.16%27%3E%3Cpath%20d%3D%27M0%20710%20C260%20670%20460%20665%20720%20698%20S1220%20745%201600%20690%27%20fill%3D%27none%27%20stroke%3D%27%23d6e3ff%27%20stroke-width%3D%2710%27/%3E%3Cpath%20d%3D%27M0%20790%20C280%20750%20490%20740%20760%20770%20S1250%20820%201600%20760%27%20fill%3D%27none%27%20stroke%3D%27%23d6e3ff%27%20stroke-width%3D%278%27/%3E%3C/g%3E%3C/svg%3E"
              alt="Mountain lake at dusk with glowing sky reflections on the water"
              width="1600"
              height="1000">
          </div>
          <figcaption>
            <div class="caption-row">
              <div>
                <h2 id="photo-title">Mountain lake at dusk</h2>
                <p class="meta">Added to your library yesterday</p>
              </div>
              <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="confirm-delete-dialog">
                Delete image
              </button>
            </div>
            <p class="meta">This image is stored locally in your library. Deleting it will remove it from the collection.</p>
          </figcaption>
        </figure>
      </article>

      <div class="empty-state" id="deleted-state" hidden>
        <strong>Image removed</strong>
        <span>The image has been deleted from your library.</span>
      </div>
    </section>
  </main>

  <dialog id="confirm-delete-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-copy">
    <div class="dialog-card">
      <div class="dialog-badge">Destructive action</div>
      <h2 id="confirm-title">Delete this image?</h2>
      <p id="confirm-copy">This will remove the image from your library. You can&apos;t undo this action.</p>
      <div class="dialog-actions">
        <button class="dialog-button cancel" type="button" data-dialog-close>Cancel</button>
        <button class="dialog-button delete" type="button" data-dialog-delete>Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('confirm-delete-dialog');
    const trigger = document.querySelector('.trigger');
    const cancelButton = dialog.querySelector('[data-dialog-close]');
    const deleteButton = dialog.querySelector('[data-dialog-delete]');
    const status = document.getElementById('status');
    const card = document.querySelector('.card');
    const deletedState = document.getElementById('deleted-state');

    function openDialog() {
      if (!dialog.open) {
        dialog.showModal();
        cancelButton.focus();
      }
    }

    trigger.addEventListener('click', openDialog);

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
      status.textContent = '';
    });

    deleteButton.addEventListener('click', () => {
      dialog.close('delete');
      card.hidden = true;
      deletedState.hidden = false;
      status.textContent = 'Image deleted from your library.';
      deletedState.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    });

    dialog.addEventListener('cancel', () => {
      status.textContent = '';
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue !== 'delete') {
        status.textContent = '';
      }
    });
  </script>
