const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
const { pathToFileURL } = require('url');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1200 } });
  await page.goto(pathToFileURL(path.resolve('index.html')).href);
  await page.waitForLoadState('networkidle');

  if (!(await page.$('.trigger'))) throw new Error('trigger class missing');
  const closed = await page.$eval('#confirm-delete-dialog', el => !el.open);
  if (!closed) throw new Error('dialog open by default');

  await page.addScriptTag({ path: axePath });
  const result = await page.evaluate(async () => await window.axe.run(document));
  const violations = result.violations.filter(v => !v.tags.includes('best-practice'));
  if (violations.length) {
    console.log(JSON.stringify(violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })), null, 2));
    process.exit(1);
  }

  await page.click('.trigger');
  if (!(await page.$eval('#confirm-delete-dialog', el => el.open))) throw new Error('dialog did not open');
  await page.keyboard.press('Escape');
  if (!(await page.$eval('#confirm-delete-dialog', el => !el.open))) throw new Error('dialog did not close on Escape');

  await browser.close();
  console.log('axe-ok');
})().catch(err => {
  console.error(err);
  process.exit(1);
});
